// Combine webhook payload with CONFIG
const all = $input.all();
const webhook = all.find(i => i.json && i.json.body) ? all.find(i=>i.json && i.json.body).json : $input.first().json;
const cfg = ($items('Config (W4)',0,0)?.[0]?.json?.CONFIG) || {};

const body = webhook.body ?? webhook;

const orderId = body.orderId || body.amazonOrderId || body.order?.amazonOrderId || null;
const pageImageUrls = Array.isArray(body.pageImageUrls) ? body.pageImageUrls : [];
const coverPngUrl = body.coverPngUrl || null;
const customer = body.customer || body.order?.customer || {};
const shippingAddress = body.shippingAddress || body.order?.shippingAddress || {};
const printOptions = body.printOptions || cfg.defaults.print;

if (!orderId) throw new Error('W4 intake: missing orderId/amazonOrderId');
if (!Array.isArray(pageImageUrls) || pageImageUrls.length === 0) throw new Error('W4 intake: pageImageUrls[] required');

const w4Payload = {
  orderId,
  pageImageUrls,
  coverPngUrl,
  customer,
  shippingAddress,
  printOptions,
  // pass through config bits we need downstream
  CONFIG: cfg,
  workflow_step: '4-print-fulfillment',
  status: 'print_fulfillment_in_progress',
  print_fulfillment_started_at: new Date().toISOString()
};

return [{ json: w4Payload }];
